232	func TestInvalidateIdempotent(t *testing.T) {
233		m := seedOccurrenceMap(t)
234		req := Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}
235		first, err := m.Invalidate(req)
236		if err != nil {
237			t.Fatal(err)
238		}
239	
240		// L 在别处再次出现（编号 2，当前有效）。
241		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
242			{Time: 300, DX: 10, Observations: []Observation{{ID: "L"}}},
243		}}); err != nil {
244			t.Fatal(err)
245		}
246	
247		// 相同操作标识 + 相同原因 + 相同集合：返回首次结果，不再撤下 occ2。
248		again, err := m.Invalidate(req)
249		if err != nil {
250			t.Fatalf("duplicate invalidation: %v", err)
251		}
252		if again.Time != first.Time || len(again.Landmarks) != 1 ||
253			again.Landmarks[0] != (InvalidatedLandmark{ID: "L", Occurrence: 1}) {
254			t.Fatalf("duplicate result = %+v, want %+v", again, first)
255		}
256		h, _ := m.LandmarkAppearances("L")
257		if !h.Appearances[1].Active {
258			t.Fatal("duplicate invalidation deactivated the new occurrence")
259		}
260	
261		// 同标识不同原因：明确拒绝。
262		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "other", Landmarks: []string{"L"}}); err == nil {
263			t.Fatal("different reason accepted")
264		} else if r, ok := AsRejectError(err); !ok || r.Kind != RejectInvalidationMismatch || r.Landmark != "op1" {
265			t.Fatalf("reason mismatch err = %v", err)
266		}
267		// 同标识不同集合：明确拒绝。
268		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"M"}}); err == nil {
269			t.Fatal("different set accepted")
270		} else if r, ok := AsRejectError(err); !ok || r.Kind != RejectInvalidationMismatch {
271			t.Fatalf("set mismatch err = %v", err)
272		}
273		// 次序不同但集合相同：仍视为重复。
274		oneMore, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}})
275		if err != nil || oneMore.Time != first.Time {
276			t.Fatalf("same set resubmit: %v %+v", err, oneMore)
277		}
278	}
