13	// readFileData 解码地图文件的 JSON 载荷。
14	func readFileData(t *testing.T, path string) fileData {
15		t.Helper()
16		raw, err := os.ReadFile(path)
17		if err != nil {
18			t.Fatal(err)
19		}
20		var fd fileData
21		if err := json.Unmarshal(raw[headerLen:len(raw)-4], &fd); err != nil {
22			t.Fatal(err)
23		}
24		return fd
25	}
26	
27	// writeFileDataRaw 用（可能被篡改的）fileData 重新组装完整文件并重算 CRC。
28	func writeFileDataRaw(t *testing.T, path string, fd *fileData) {
29		t.Helper()
30		payload, err := json.Marshal(fd)
31		if err != nil {
32			t.Fatal(err)
33		}
34		out := make([]byte, headerLen+len(payload)+4)
35		copy(out[0:8], fileMagic)
36		binary.BigEndian.PutUint16(out[8:10], fileVersion)
37		binary.BigEndian.PutUint32(out[10:14], uint32(len(payload)))
38		copy(out[headerLen:], payload)
39		binary.BigEndian.PutUint32(out[len(out)-4:], crc32.ChecksumIEEE(out[:len(out)-4]))
40		if err := os.WriteFile(path, out, 0o644); err != nil {
41			t.Fatal(err)
42		}
43	}
44	
45	// buildOccurrenceMap 构造含同一路标两次出现的地图：L 在 t=100、200 被
46	// 观测，t=200 失效，t=300 再次被观测。
47	func buildOccurrenceMap(t *testing.T, path string) {
48		t.Helper()
49		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
50		m, err := Create(path, cfg)
51		if err != nil {
52			t.Fatal(err)
53		}
54		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
55			{Time: 100, DX: 1, Observations: []Observation{{ID: "L"}}},
56			{Time: 200, DX: 1, Observations: []Observation{{ID: "L"}}},
57		}}); err != nil {
58			t.Fatal(err)
59		}
60		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
61			t.Fatal(err)
62		}
63		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
64			{Time: 300, DX: 1, Observations: []Observation{{ID: "L"}}},
65		}}); err != nil {
66			t.Fatal(err)
67		}
68		if err := m.Close(); err != nil {
69			t.Fatal(err)
70		}
71	}
72	
73	// 正常文件：失效端点（200）属于已失效的第一次出现，再现端点（300）属于
74	// 第二次出现，打开成功且记录原样保留。
75	func TestOpenObservationOwnershipValid(t *testing.T) {
76		path := filepath.Join(t.TempDir(), "m.pose")
77		buildOccurrenceMap(t, path)
78	
79		m, err := Open(path)
80		if err != nil {
81			t.Fatalf("open: %v", err)
82		}
83		defer m.Close()
84		h, err := m.LandmarkAppearances("L")
85		if err != nil {
86			t.Fatal(err)
87		}
88		if len(h.Appearances) != 2 {
89			t.Fatalf("appearances = %+v", h.Appearances)
90		}
91		a1, a2 := h.Appearances[0], h.Appearances[1]
92		if a1.Active || a1.FirstSeenTime != 100 || a1.InvalidTime != 200 || a1.Landmark.Count != 2 {
93			t.Fatalf("occ1 = %+v", a1)
94		}
95		if !a2.Active || a2.FirstSeenTime != 300 || a2.Landmark.Count != 1 {
96			t.Fatalf("occ2 = %+v", a2)
97		}
98		// 查询行为不变。
99		if p, err := m.PoseAt(250); err != nil || p.Time != 200 {
100			t.Fatalf("PoseAt(250) = %+v %v", p, err)
101		}
102		if cur, err := m.CurrentPose(); err != nil || cur.Time != 300 {
103			t.Fatalf("CurrentPose = %+v %v", cur, err)
104		}
105	}
