107	// 逐帧观测指向不存在的路标：打开即报 ErrCorrupt，不返回地图对象。
108	// 拒绝时不改写原文件（另见 TestOpenRejectionLeavesFileUntouched）。
109	func TestOpenRejectsUnknownLandmarkObservation(t *testing.T) {
110		path := filepath.Join(t.TempDir(), "m.pose")
111		buildOccurrenceMap(t, path)
112		fd := readFileData(t, path)
113		fd.Sources[0].Observations[0].ID = "GHOST"
114		writeFileDataRaw(t, path, &fd)
115	
116		m, err := Open(path)
117		if !errors.Is(err, ErrCorrupt) {
118			t.Fatalf("err = %v, want ErrCorrupt", err)
119		}
120		if m != nil {
121			t.Fatalf("Open returned usable map: %v", m)
122		}
123	}
124	
125	// Open 拒绝后原文件内容必须保持不变。
126	func TestOpenRejectionLeavesFileUntouched(t *testing.T) {
127		path := filepath.Join(t.TempDir(), "m.pose")
128		buildOccurrenceMap(t, path)
129		fd := readFileData(t, path)
130		fd.Sources[1].Observations[0].ID = "GHOST"
131		writeFileDataRaw(t, path, &fd)
132		saved, err := os.ReadFile(path)
133		if err != nil {
134			t.Fatal(err)
135		}
136		if m, err := Open(path); !errors.Is(err, ErrCorrupt) {
137			t.Fatalf("err = %v, want ErrCorrupt, map=%v", err, m)
138		}
139		got, err := os.ReadFile(path)
140		if err != nil {
141			t.Fatal(err)
142		}
143		if string(got) != string(saved) {
144			t.Fatal("Open modified the rejected file")
145		}
146	}
