	if err != nil {
		t.Fatal(err)
	}
	if len(hM.Appearances) != 1 || hM.Appearances[0].Active ||
		hM.Appearances[0].InvalidOpID != "A" || hM.Appearances[0].InvalidTime != 200 {
		t.Fatalf("M occ1 = %+v", hM.Appearances[0])
